public void saveBlogEntry(BlogEntry blogEntry, BlogEntryText blogEntryText, boolean trusted) throws JPersistException, IOException
      {
        String internalName = blogEntry.getInternalName();
        boolean isPersistent = blogEntry.isPersistent();

        if (! trusted)
          validateAndFixHtml(blogEntry, blogEntryText);
        
        blogEntry.setInternalName(createInternalName(blogEntry.getTitle()));
        
        getDatabaseManager().saveObject(blogEntry);
        
        if (blogEntryText.getBlogText() != null && blogEntryText.getBlogText().length() > 0)
          {
            blogEntryText.setBlogEntryId(blogEntry.getBlogEntryId());
            getDatabaseManager().saveObject(blogEntryText);
          }
        
        if (!isPersistent)
          {
            addToActivityQueue(blogEntry);

            blogEntryMapById.put(blogEntry.getBlogEntryId(), blogEntry);
            blogEntryMapByName.put(blogEntry.getInternalName(), blogEntry);
            blogEntryQueue.add(blogEntry);
            
            if (blogEntryQueue.size() > maxEntries)
              {
                BlogEntry removedEntry = blogEntryQueue.remove();
                blogEntryMapById.remove(removedEntry.getBlogEntryId());
                blogEntryMapByName.remove(removedEntry.getInternalName());
              }
          }
        else
          {
            if (!blogEntry.getInternalName().equals(internalName))
              {
                blogEntryMapByName.remove(internalName);
                blogEntryMapByName.put(blogEntry.getInternalName(), blogEntry);
              }
            
            blogEntry.wasUpdated = true;
          }
        
        addToIndexQueue.add(blogEntry);
      }

public void saveBlogComment(BlogEntryComment blogEntryComment) throws JPersistException, IOException
      {
        blogEntryComment.setAuthor(htmlValidator.validateAndCorrect(blogEntryComment.getAuthor(), true));
        blogEntryComment.setCommentText(htmlValidator.validateAndCorrect(blogEntryComment.getCommentText()));
        
        getDatabaseManager().saveObject(blogEntryComment);
        getBlogEntryComments(blogEntryComment.getBlogEntryId()).put(blogEntryComment.getBlogEntryCommentId(), blogEntryComment);
      }

