public void writeFeed(String title, Writer writer, Iterator<BlogEntry> iterator, int risingOrPopular, String feedType, String feedLink, String contextServletPath) throws IOException, FeedException, JPersistException
      {
        SyndFeed feed = new SyndFeedImpl();

        feed.setFeedType(feedType);
        feed.setTitle(properties.getProperty("feedTitle") + title);
        feed.setLink(feedLink);
        feed.setDescription(properties.getProperty("feedDescription"));
        feed.setAuthor(properties.getProperty("feedAuthor"));
        feed.setCopyright(properties.getProperty("feedCopyright"));

        List<SyndEntry> syndEntryList = new ArrayList<SyndEntry>();

        for (Iterator<BlogEntry> it = iterator; it.hasNext();)
          {
            BlogEntry blogEntry = it.next();
            SyndEntry syndEntry = new SyndEntryImpl();

            if (feedType.equalsIgnoreCase("rss_0.9") && blogEntry.getTitle().length() > 100)
              syndEntry.setTitle(blogEntry.getTitle().substring(0, 100));
            else
              syndEntry.setTitle(blogEntry.getTitle());

            syndEntry.setAuthor(blogEntry.getAuthor());
            syndEntry.setLink(contextServletPath + blogEntry.getBlogEntryId() + "/" + blogEntry.getInternalName() + ".html");
            
            if (risingOrPopular == 2 && blogEntry.getPopularTime() != null)
              syndEntry.setPublishedDate(blogEntry.getPopularTime());
            else if (risingOrPopular == 1 && blogEntry.getRisingTime() != null)
              syndEntry.setPublishedDate(blogEntry.getRisingTime());
            else 
              syndEntry.setPublishedDate(blogEntry.getCreated());

            SyndContent content = new SyndContentImpl();
            content.setType("text/html");
            content.setValue(blogEntry.getDescription());
            syndEntry.setDescription(content);

            if (addEntryToFeed)
              {
                BlogEntryText blogEntryText = getBlogEntryText(blogEntry.getBlogEntryId());
                
                if (blogEntryText != null)
                  {
                    ArrayList<SyndContent> contentList = new ArrayList<SyndContent>();

                    content = new SyndContentImpl();
                    content.setType("text/html");
                    content.setValue(blogEntryText.getBlogText());
                    contentList.add(content);
                    syndEntry.setContents(contentList);
                  }
              }
            
            syndEntryList.add(syndEntry);
          }

        if (syndEntryList.size() == 0)
          {
            SyndEntry syndEntry = new SyndEntryImpl();

            syndEntry.setTitle("There are no entries at this time.  Thank you.");
            syndEntry.setAuthor(properties.getProperty("feedAuthor"));
            syndEntry.setLink(feedLink);

            syndEntryList.add(syndEntry);
          }
        
