        if (addDescriptionToIndex)
          doc.add(new Field("description", blogEntry.getDescription(), Field.Store.NO, Field.Index.ANALYZED));

        BlogEntryText blogEntryText = getBlogEntryText(blogEntry.getBlogEntryId());

        if (addEntryToIndex && blogEntryText != null && blogEntryText.getBlogText() != null)
          doc.add(new Field("article", blogEntryText.getBlogText(), Field.Store.NO, Field.Index.ANALYZED));

        if (blogEntry.wasUpdated)
          indexWriter.updateDocument(new Term("blogEntryId", "" + blogEntry.getBlogEntryId()), doc);
        else
          indexWriter.addDocument(doc);
