                            blogEntry.setTitle(syndEntry.getTitle());
                            blogEntry.setHasComments("true");
                            blogEntry.setHasAnonymousComments("true");
                            blogEntry.setIsVisible("true");
                            
                            String tags = externalFeed.addTags;
                            List<SyndCategory> categories = syndEntry.getCategories();

                            for (SyndCategory syndCategory : categories)
                              tags += ", " + syndCategory.getName();

                            blogEntry.setTags(tags);

                            BlogEntryText blogEntryText = new BlogEntryText();

                            if (externalFeed.useContent)
                              {
                                List<SyndContent> contents = syndEntry.getContents();
