void processHtml(Iterator<Segment> iterator, StringBuilder stringBuilder)
      {
        while (iterator.hasNext())
          {
            Segment segment = iterator.next();

            if (segment instanceof Tag)
              {
                String tagName = ((Tag)segment).getName();

                if (isTagAllowed(tagName))
                  {
                    AllowedAttributes allowedAttributes = getAllowedAttributes(tagName);

                    if (segment instanceof StartTag)
                      {
                        for (Iterator<Attribute> it = ((StartTag)segment).getAttributes().iterator(); it.hasNext();)
                          {
                            Attribute attribute = it.next();

                            if (!allowedAttributes.attributeAllowed(attribute.getName()))
                              it.remove();
                          }
                      }

                    stringBuilder.append(((Tag)segment).tidy());
                  }
              }
            else
              {
                if (stringBuilder.length() > 0 && stringBuilder.charAt(stringBuilder.length() - 1) != ' ')
                  stringBuilder.append(" ");

                stringBuilder.append(escapeAndFixText(segment.getTextExtractor().toString()));
              }
          }
      }

